/* R1.1 — one-use DUDU invitation, dormant until reviewed Rules are live.
 * The code is generated by the owner via Web Crypto and never hardcoded.
 * Firestore Rules (not this UI) must require the atomic invite redemption.
 */
(function(root,factory){
 'use strict';
 const api=factory(root);
 if(typeof module==='object'&&module.exports)module.exports=api;
 if(root)root.DuduAccountInviteR11=api;
})(typeof window!=='undefined'?window:null,function(root){
 'use strict';
 const COLLECTION='invite_codes_r11';
 const APPROVED='approved_accounts_v1';
 const ALPHABET='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
 const CODE_PATTERN=/^DUDU-[A-HJ-NP-Z2-9]{8}-[A-HJ-NP-Z2-9]{8}$/;
 const fail=code=>Object.assign(new Error(code),{code});
 function normalize(code){return String(code||'').trim().toUpperCase().replace(/\s+/g,'');}
 function validCode(code){return CODE_PATTERN.test(normalize(code));}
 function generate(secureCrypto=root?.crypto){
  if(!secureCrypto?.getRandomValues)throw fail('secure-random-unavailable');
  const bytes=new Uint8Array(16);
  secureCrypto.getRandomValues(bytes);
  const id=Array.from(bytes,n=>ALPHABET[n&31]).join('');
  return 'DUDU-'+id.slice(0,8)+'-'+id.slice(8);
 }
 function session(auth){
  const user=auth?.currentUser;
  if(!user?.uid||user.uid.length>128)throw fail('login-required');
  return user;
 }
 function stamp(){
  const server=root?.firebase?.firestore?.FieldValue?.serverTimestamp?.();
  if(!server)throw fail('server-timestamp-unavailable');
  return server;
 }
 async function create({db,auth}={}){
  const user=session(auth);
  if(!user.getIdTokenResult||!db?.collection)throw fail('firebase-unavailable');
  const token=await user.getIdTokenResult();
  if(auth.currentUser!==user||token?.claims?.admin!==true)throw fail('admin-required');
  const code=generate();
  const expiresAt=root?.firebase?.firestore?.Timestamp?.fromDate?.(
   new Date(Date.now()+6*24*60*60*1000));
  if(!expiresAt)throw fail('firestore-timestamp-unavailable');
  await db.collection(COLLECTION).doc(code).set({
   createdBy:user.uid,createdAt:stamp(),expiresAt,status:'open',
   redeemedBy:'',redeemedAt:null
  });
  if(auth.currentUser!==user)throw fail('account-changed');
  return {code,expiresAt};
 }
 async function redeem({db,auth,code}={}){
  const user=session(auth);
  const invite=normalize(code);
  if(!validCode(invite))throw fail('invalid-code-format');
  if(!db?.batch||!db?.collection)throw fail('firebase-unavailable');
  const batch=db.batch();
  batch.update(db.collection(COLLECTION).doc(invite),{
   status:'redeemed',redeemedBy:user.uid,redeemedAt:stamp()
  });
  batch.set(db.collection(APPROVED).doc(user.uid),{
   uid:user.uid,enabled:true,approvedAt:stamp(),approvedBy:'invite',inviteCode:invite
  });
  if(auth.currentUser!==user)throw fail('account-changed');
  // Either the code and approval are both written, or neither is written.
  await batch.commit();
  if(auth.currentUser!==user)throw fail('account-changed');
  return {approved:true,uid:user.uid};
 }
 return Object.freeze({COLLECTION,APPROVED,normalize,validCode,generate,create,redeem});
});
